-- 2026-11-13 A2-2.3.5：删除第3条夹带的“【2007 真题】”及选项和试题分析
begin;
create temp table _kba235rm(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kba235rm values (78, $kba235rm$[{"t":"list","id":"a2-2-3-5-b1","imp":"core","items":["1、==常用程序设计语言==","==（1）FORTRAN∶面向过程程序设计言，用于数值计算。==","==（2）Java∶跨平台，适用于网络，面向对象程序设计语言，（单继承）。==","==（3）C 面向过程,多用于系统、底层软件的开发等，linux 内核是C 写的。==","==（4）C++;面向对象（多继承）。==","==（5）C#;面向对象（单继承）。==","==（7）VB:面向对象==","==（8）BASIC 面向过程或结构化程序设计语言。==","==（9）人工智能语言主要有LISP、Prolog、Smalltalk、C++等。==","==（10）脚本语言：VBA、JavaScript、VBScript、ActionScript、PHP 等==","2、==汇编语言==：==使用助记符来替代机器指令的二进制代码==，如 ADD 表示加法、SUB 表示减法、MOV 表示传送数据。 操作数使用十六进制编码，较易理解。 不可以直接执行，需要由汇编程序翻译成机器语言后才能执行。 执行速度较快。 不可以移植，依赖于具体的计算机指令系统。 同机器语言一样属于低级语言。","3、==其他程序设计语言==：除了以上介绍的几种程序语言外，有影响的程序语言还有：","^^LISP 语言^^：适用于==符号操作和表处理==，主要用于人工智能领域。","^^PROLOG 语言^^：一种==逻辑式编程语言==，主要用于人工智能领域。","^^Ada 语言^^：类似于 PASCAL 语言，且易于==控制并行任务和处理异常情况==，适于军用。","4、==软件技术的四代发展==：^^软件技术的发展^^：","1. ^^第一代（20 世纪 50—60 年代）^^：==以 ALGOL、FORTRAN 等编程语言为标志==，高级语言出现。","2. ^^第二代（20 世纪 70 年代）^^：==以 Pascal、COBOL 和 C 等编程语言以及关系数据库管理系统为标志==的结构化程序设计软件技术。","3. ^^第三代（20 世纪 80 年代）^^：==以 Smalltalk、C++ 等为代表的面向对象技术（OO）==出现。","4. ^^第四代（20 世纪 90 年代）^^：==以 COM、CORBA 等为代表的分布式面向对象技术（DOO）和构件技术==。","5、^^ALGOL 与 PASCAL 语言^^：ALGOL（ALGOrithmic Language）语言：分别于 1960 年和 1962 年发表的 ALGOL60 报告及修改报告，已成为程序设计语言发展史上的里程碑，不但开拓了程序设计语言的研究领域，也为后来的软件自动化和软件可靠性研究奠定了基础。ALGOL 语言的语法和语义均有严格的描述，其语法描述采用了巴科斯范式（BNF），结构清晰、理论严谨。 在 ALGOL 语言基础上发展的 ALGOL 语言簇包括 ^^ALGOL68、Simula、PASCAL 等^^。","6、^^Android 的应用程序^^：Android 会同一系列核心应用程序包一起发布，该应用程序包包括^^客户端、SMS 短消息程序、日历、地图、浏览器、联系人管理程序等^^。所有的应用程序都是使用 Java 语言编写的。","7、^^BASIC 和 Visual Basic 语言^^：^^BASIC 是一种简单易学的计算机高级语言^^。Visual Basic（VB）是微软公司在 BASIC 基础上开发的一种程序设计语言，具有很强的可视化设计功能，给用户在 Windows 环境下开发软件带来了方便，是重要的多媒体编程工具语言，也为网页功能的扩展和 Web 应用提供了很大方便。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-3-5-b2","imp":"core","kind":"tip","text":"常用语言定位：==C 语言（底层系统开发、嵌入式首选）、C++（高性能系统与游戏开发）、Java（跨平台企业级后端与 Android）、Python（人工智能、数据科学与脚本自动化）、JavaScript（Web 前端交互与 Node.js 后端）==。","title":"考向复习提示：主流编程语言应用场景对号入座"},{"t":"callout","id":"a2-2-3-5-b3","imp":"core","kind":"trap","text":"面向对象（OOP）三大核心支柱：==封装（隐藏内部实现提供接口）、继承（代码复用与层次建模）、多态（同一操作作用于不同对象产生不同行为）==；常考辨析：==方法重载（Overload，编译期多态/静态绑定）==与==方法重写（Override，运行期多态/动态绑定）==的区别，务必牢记重载发生在同一个类中，重写发生在父子类继承体系中。","title":"高频易错陷阱：面向对象三大特征与多态判定"}]$kba235rm$::jsonb, $kba235rmse$A2-2.3.5 常用程序设计语言。 1、常用程序设计语言 （1）FORTRAN∶面向过程程序设计言，用于数值计算。 （2）Java∶跨平台，适用于网络，面向对象程序设计语言，（单继承）。 （3）C 面向过程,多用于系统、底层软件的开发等，linux 内核是C 写的。 （4）C++;面向对象（多继承）。 （5）C#;面向对象（单继承）。 （7）VB:面向对象 （8）BASIC 面向过程或结构化程序设计语言。 （9）人工智能语言主要有LISP、Prolog、Smalltalk、C++等。 （10）脚本语言：VBA、JavaScript、VBScript、ActionScript、PHP 等 2、汇编语言：使用助记符来替代机器指令的二进制代码，如 ADD 表示加法、SUB 表示减法、MOV 表示传送数据。 操作数使用十六进制编码，较易理解。 不可以直接执行，需要由汇编程序翻译成机器语言后才能执行。 执行速度较快。 不可以移植，依赖于具体的计算机指令系统。 同机器语言一样属于低级语言。 3、其他程序设计语言：除了以上介绍的几种程序语言外，有影响的程序语言还有： LISP 语言：适用于符号操作和表处理，主要用于人工智能领域。 PROLOG 语言：一种逻辑式编程语言，主要用于人工智能领域。 Ada 语言：类似于 PASCAL 语言，且易于控制并行任务和处理异常情况，适于军用。 4、软件技术的四代发展：软件技术的发展： 1. 第一代（20 世纪 50—60 年代）：以 ALGOL、FORTRAN 等编程语言为标志，高级语言出现。 2. 第二代（20 世纪 70 年代）：以 Pascal、COBOL 和 C 等编程语言以及关系数据库管理系统为标志的结构化程序设计软件技术。 3. 第三代（20 世纪 80 年代）：以 Smalltalk、C++ 等为代表的面向对象技术（OO）出现。 4. 第四代（20 世纪 90 年代）：以 COM、CORBA 等为代表的分布式面向对象技术（DOO）和构件技术。 5、ALGOL 与 PASCAL 语言：ALGOL（ALGOrithmic Language）语言：分别于 1960 年和 1962 年发表的 ALGOL60 报告及修改报告，已成为程序设计语言发展史上的里程碑，不但开拓了程序设计语言的研究领域，也为后来的软件自动化和软件可靠性研究奠定了基础。ALGOL 语言的语法和语义均有严格的描述，其语法描述采用了巴科斯范式（BNF），结构清晰、理论严谨。 在 ALGOL 语言基础上发展的 ALGOL 语言簇包括 ALGOL68、Simula、PASCAL 等。 6、Android 的应用程序：Android 会同一系列核心应用程序包一起发布，该应用程序包包括客户端、SMS 短消息程序、日历、地图、浏览器、联系人管理程序等。所有的应用程序都是使用 Java 语言编写的。 7、BASIC 和 Visual Basic 语言：BASIC 是一种简单易学的计算机高级语言。Visual Basic（VB）是微软公司在 BASIC 基础上开发的一种程序设计语言，具有很强的可视化设计功能，给用户在 Windows 环境下开发软件带来了方便，是重要的多媒体编程工具语言，也为网页功能的扩展和 Web 应用提供了很大方便。 考向复习提示：主流编程语言应用场景对号入座 常用语言定位：C 语言（底层系统开发、嵌入式首选）、C++（高性能系统与游戏开发）、Java（跨平台企业级后端与 Android）、Python（人工智能、数据科学与脚本自动化）、JavaScript（Web 前端交互与 Node.js 后端）。 高频易错陷阱：面向对象三大特征与多态判定 面向对象（OOP）三大核心支柱：封装（隐藏内部实现提供接口）、继承（代码复用与层次建模）、多态（同一操作作用于不同对象产生不同行为）；常考辨析：方法重载（Overload，编译期多态/静态绑定）与方法重写（Override，运行期多态/动态绑定）的区别，务必牢记重载发生在同一个类中，重写发生在父子类继承体系中。$kba235rmse$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kba235rm loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
